#!/usr/bin/env bash
# cleanup.sh — Remove all build and simulation artifacts for sram
# Usage: bash IP/system/sram/cleanup.sh
#
# Only generated files are removed; sources, scripts, waivers, committed
# reports and results logs that document verification runs are kept.
# Tool scripts that do not exist yet (later steps) are skipped.

# Guard: require CLAUDE_SRAM_PATH
if [ -z "${CLAUDE_SRAM_PATH}" ]; then
    echo "ERROR: CLAUDE_SRAM_PATH is not set."
    echo "       Please run:  source IP/system/sram/setup.sh"
    exit 1
fi

set -e

echo "Cleaning sram build and simulation artifacts..."

# Run a cleanup helper only once its step has created it.
_run_if_present() {
    local tool="$1"
    shift
    if [ -f "${tool}" ]; then
        "$@"
    fi
}

# Simulator working directories (Icarus/GHDL/ModelSim/VCS/Xcelium)
rm -rf "${CLAUDE_SRAM_PATH}/verification/work"/*

# Vivado simulation projects (generated by create_project_*.tcl)
rm -rf "${CLAUDE_SRAM_PATH}/verification/vivado/work"

# Firmware build artifacts
rm -rf "${CLAUDE_SRAM_PATH}/firmware/build" \
       "${CLAUDE_SRAM_PATH}/firmware/obj" \
       "${CLAUDE_SRAM_PATH}/firmware/lib"

# Synthesis outputs (Vivado/Quartus/Yosys, Design Compiler, PrimeTime)
_run_if_present "${CLAUDE_SRAM_PATH}/synthesis/run_vendor_synth.py" \
    python3 "${CLAUDE_SRAM_PATH}/synthesis/run_vendor_synth.py" --clean
_run_if_present "${CLAUDE_SRAM_PATH}/synthesis/clean.sh" \
    bash "${CLAUDE_SRAM_PATH}/synthesis/clean.sh"
_run_if_present "${CLAUDE_SRAM_PATH}/synthesis/run_primetime_sta.py" \
    python3 "${CLAUDE_SRAM_PATH}/synthesis/run_primetime_sta.py" --clean

# Formal verification run directories (keep scripts, properties, results logs)
rm -rf "${CLAUDE_SRAM_PATH}/verification/formal/work"
_run_if_present "${CLAUDE_SRAM_PATH}/verification/tools/formal_sram.py" \
    python3 "${CLAUDE_SRAM_PATH}/verification/tools/formal_sram.py" --clean

# Lint logs (keep config and waivers)
rm -f "${CLAUDE_SRAM_PATH}/verification/lint/lint_results.log"

# SpyGlass lint intermediates (csun.edu only — keep the .prj files)
rm -rf "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/vcst_rtdb" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/vcst_rtdb.bak" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/"*.prj.tcl* \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/vcst_command.log" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/vcst_session.log"* \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/.vcstPref" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/spyglass.out" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/report_hdl.txt" \
       "${CLAUDE_SRAM_PATH}/verification/lint/spyglass/VCSOptFile.txt"

# Files Synopsys tools drop into whatever directory they are launched from
# (dc_shell/pt_shell/lc_shell command logs, fsdb2vcd/Verdi/VCS scratch) — left
# behind when a tool is run by hand from the IP root or the tools directory.
for dir in "${CLAUDE_SRAM_PATH}" "${CLAUDE_SRAM_PATH}/verification/tools"; do
    rm -rf "${dir}/command.log" \
           "${dir}/"*_command.log \
           "${dir}/fsdb2vcdLog" \
           "${dir}/verdiLog" \
           "${dir}/novas_dump.log" \
           "${dir}/ucli.key" \
           "${dir}/DVEfiles" \
           "${dir}/csrc" \
           "${dir}/simv" "${dir}/simv.daidir" \
           "${dir}/vcdplus.vpd" \
           "${dir}/.rce"
done

# Python cache directories
find "${CLAUDE_SRAM_PATH}" -type d -name "__pycache__" -exec rm -rf {} + 2>/dev/null || true
find "${CLAUDE_SRAM_PATH}" \( -name "*.pyc" -o -name "*.pyo" \) -exec rm -f {} + 2>/dev/null || true

echo "Clean complete."
